{
  "claims": [
    {
      "agent": "NOC",
      "type": "action",
      "verb": "rollback_model",
      "params": {
        "model": "fraud_model_v2",
        "reason": "high_false_positive_on_prepaid_roaming"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I3"
      ],
      "rationale": "The v2 model is refusing about 2,750 legitimate SIM replacement requests since go-live, concentrated on prepaid and roaming profiles. Rolling back stops the ongoing harm while preserving known fraud blocking.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "The record reflects that the vast majority of SIM change and port-out requests are legitimate. It also shows that the efficient and effective processing of SIM changes and port-out requests promotes customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "enable_review_queue",
      "params": {
        "queue_name": "sim_refusal_human_review",
        "criteria": "prepaid_roaming_false_positives"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "No human review path exists for refused requests. Enabling a review queue gives legitimate customers a way to appeal automated refusals and aligns with the clear reporting and remediation process expected for SIM swap incidents.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "Notify affected customers that their SIM replacement request was refused due to the fraud model and provide a way to request human review.",
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "Customer notification is an early warning that enables customers to act promptly. Currently there is no human review path, which frustrates customers and increases harm.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0022",
          "quote": "to provide customers with an early warning that their account may be subject to fraudulent activity, we adopt our proposal to require wireless providers to provide immediate notification to customers of any requests for a SIM change associated with the customer's account"
        }
      ],
      "deadline_hours": 24
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "open_incident",
      "params": {
        "incident_type": "SIM_swap_fraud_model_false_positives",
        "severity": "high"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I2",
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "Multiple institutions report service lockouts and customer complaints. Opening a formal incident coordinates the regulatory response and preserves evidence for any enforcement.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "direction": "restore_legitimate_sim_replacement_access",
        "deadline_hours": 24
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "The ongoing refusal of legitimate requests is causing consumer harm. A direction compels OpCo to implement interim measures such as human review or rollback.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "The record reflects that the vast majority of SIM change and port-out requests are legitimate. It also shows that the efficient and effective processing of SIM changes and port-out requests promotes customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No UAE legal instrument is identified in the provided knowledge that sets the authentication requirements an operator must apply to SIM-swap requests; only US FCC global precedent is available.",
      "inject_refs": [
        "S3-I5"
      ],
      "rationale": "The regulator's internal question explicitly asks which UAE instrument applies, and the knowledge base contains no UAE SIM-swap authentication rule, creating regulatory uncertainty.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "open_investigation",
      "params": {
        "subject": "automated_SIM_swap_refusal_no_appeal"
      },
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Customer group complains that automated decisions refused SIM replacement with no explanation and no way to appeal. DPA should investigate whether automated decision-making rights are being violated.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "request_human_review_record",
      "params": {
        "scope": "SIM_replacement_refusals_since_08_00"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "There is no human review path for refused requests. DPA should require OpCo to produce records to evidence whether any human review exists and how decisions are made.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0063",
          "quote": "Our requirement that wireless providers maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud rests on our concern that customers currently struggle to report SIM swap and port-out fraud to their wireless providers."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No rule in the provided knowledge requires a human review or appeal process for automated SIM replacement refusals, leaving customers without remedy.",
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "The incident shows automated refusals with no explanation and no appeal, and the available global rules focus on fraud reporting, not on appeal rights for false positives.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "instruction": "activate_in_app_authentication_for_affected_customers",
        "scope": "customers_abroad"
      },
      "inject_refs": [
        "S3-I2"
      ],
      "rationale": "Banks report customers abroad cannot receive OTPs and are locked out. FIN should instruct banks to activate mobile app or other non-SMS authentication for affected customers, consistent with the industry move away from SMS OTP.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "UAE banks will stop sending OTPs via SMS and email for online transactions by July 25, 2025. Customers must authenticate transactions using their mobile banking apps for improved security."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "action",
      "verb": "request_info",
      "params": {
        "request": "affected_MSISDNs_and_incident_timeline"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I2"
      ],
      "rationale": "FIN needs to know which bank customers are affected by the SIM replacement refusals and the expected duration to coordinate bank-side mitigation.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "Customers travelling outside the UAE have complained of not receiving the SMS containing the OTP or receiving it after the valid time period."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "gap",
      "gap_type": "overlap",
      "statement": "The incident exposes overlapping but uncoordinated authentication rules: OpCo's SIM swap authentication blocks legitimate replacement, while banks still rely on SMS OTP, causing cascading lockout.",
      "inject_refs": [
        "S3-I2",
        "S3-I3"
      ],
      "rationale": "No known UAE cross-sector rule requires coordination between mobile operators' SIM replacement controls and financial institutions' OTP authentication, so a telecom false-positive wave becomes a banking access outage.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "Customers travelling outside the UAE have complained of not receiving the SMS containing the OTP or receiving it after the valid time period."
        },
        {
          "chunk_id": "US-FCC-23-95#0064",
          "quote": "telecommunications carriers are 'but one link in the chain of consumer and business protection from account takeover fraud,' and therefore that the responsibility for financial harms that a bad actor may be able to perpetuate following such fraud is borne by several parties, including, significantly, the bad actor."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0064",
          "quote": "telecommunications carriers are 'but one link in the chain of consumer and business protection from account takeover fraud,' and therefore that the responsibility for financial harms that a bad actor may be able to perpetuate following such fraud is borne by several parties, including, significantly, the bad actor."
        }
      ]
    }
  ]
}
